package com.nolanbaker.pgmodernized.ponder;

import com.nolanbaker.pgmodernized.PowerGridModernized;
import net.createmod.ponder.api.registration.PonderPlugin;
import net.createmod.ponder.api.registration.PonderSceneRegistrationHelper;
import net.createmod.ponder.api.registration.PonderTagRegistrationHelper;
import net.minecraft.resources.ResourceLocation;

/**
 * The mod's Ponder scenes: hold W on an item for a tour of what it does. Scenes are scripted in
 * {@link PgmPonderScenes}; their plots are generated by {@code tools/gen_ponder_schematics.py} and
 * their text keys by {@code tools/gen_ponder_lang.py}. Client only.
 */
public class PgmPonderPlugin implements PonderPlugin {
    @Override
    public String getModId() {
        return PowerGridModernized.MOD_ID;
    }

    @Override
    public void registerScenes(PonderSceneRegistrationHelper<ResourceLocation> helper) {
        PgmPonderScenes.register(helper);
    }

    @Override
    public void registerTags(PonderTagRegistrationHelper<ResourceLocation> helper) {
        PgmPonderTags.register(helper);
    }
}
